-- 开物录初始数据。请先选择目标数据库，再导入此文件。

BEGIN;
SELECT pg_advisory_xact_lock(82422402);

CREATE TABLE IF NOT EXISTS "categories" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "slug" varchar(64),
  "name" varchar(64),
  "parent_slug" varchar(64),
  "kind" varchar(16),
  "content_kind" varchar(16),
  "sort" bigint,
  "show_on_home" boolean,
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "links" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "imported_from" varchar(96),
  "slug" varchar(80),
  "category_slug" varchar(64),
  "name" varchar(128),
  "url" varchar(512),
  "desc" varchar(256),
  "tags" varchar(160),
  "alias" varchar(64),
  "lang" varchar(32),
  "region" varchar(32),
  "spare" varchar(512),
  "icp" varchar(64),
  "body" text,
  "pinned" boolean,
  "pin_sort" bigint,
  "sort" bigint,
  "clicks" bigint,
  "views" bigint,
  "checked_at" timestamptz(3) NULL,
  "check_fails" bigint,
  "status" varchar(16),
  "user_id" bigint,
  "created_at" timestamptz(3) NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "articles" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "legacy_id" varchar(64),
  "legacy_slug" varchar(255),
  "title" varchar(255),
  "summary" text,
  "body" text,
  "format" varchar(16),
  "cover_url" varchar(512),
  "video_url" varchar(512),
  "category" varchar(64),
  "featured" boolean,
  "sort" bigint,
  "draft" boolean NOT NULL DEFAULT false,
  "views" bigint,
  "created_at" timestamptz(3) NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "tags" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "group" varchar(32),
  "name" varchar(64),
  "sort" bigint,
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "category_guides" (
  "category_slug" varchar(64),
  "title" varchar(128),
  "intro" text,
  "home_label" varchar(64),
  PRIMARY KEY ("category_slug")
);

CREATE TABLE IF NOT EXISTS "history_events" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "month" bigint NOT NULL,
  "day" bigint NOT NULL,
  "year" bigint NOT NULL,
  "text" varchar(255) NOT NULL,
  PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX IF NOT EXISTS "idx_categories_slug" ON "categories" ("slug");
CREATE INDEX IF NOT EXISTS "idx_categories_parent_slug" ON "categories" ("parent_slug");
CREATE UNIQUE INDEX IF NOT EXISTS "idx_links_imported_from" ON "links" ("imported_from");
CREATE INDEX IF NOT EXISTS "idx_links_slug" ON "links" ("slug");
CREATE INDEX IF NOT EXISTS "idx_links_category_slug" ON "links" ("category_slug");
CREATE INDEX IF NOT EXISTS "idx_links_status" ON "links" ("status");
CREATE INDEX IF NOT EXISTS "idx_links_user_id" ON "links" ("user_id");
CREATE UNIQUE INDEX IF NOT EXISTS "idx_articles_legacy_id" ON "articles" ("legacy_id");
CREATE INDEX IF NOT EXISTS "idx_articles_legacy_slug" ON "articles" ("legacy_slug");
CREATE INDEX IF NOT EXISTS "idx_articles_category" ON "articles" ("category");
CREATE INDEX IF NOT EXISTS "idx_articles_draft" ON "articles" ("draft");
CREATE INDEX IF NOT EXISTS "idx_tags_group" ON "tags" ("group");
CREATE UNIQUE INDEX IF NOT EXISTS "ux_history_event" ON "history_events" ("month","day","year","text");

-- Fill a completely empty content database once.
CREATE TEMP TABLE kaiwulu_init_state ON COMMIT DROP AS
SELECT NOT EXISTS (SELECT 1 FROM categories)
   AND NOT EXISTS (SELECT 1 FROM links)
   AND NOT EXISTS (SELECT 1 FROM articles)
   AND NOT EXISTS (SELECT 1 FROM tags)
   AND NOT EXISTS (SELECT 1 FROM category_guides)
   AND NOT EXISTS (SELECT 1 FROM history_events) AS populate;

INSERT INTO "categories" ("id", "slug", "name", "parent_slug", "kind", "content_kind", "sort", "show_on_home")
SELECT seed."id", seed."slug", seed."name", seed."parent_slug", seed."kind", seed."content_kind", seed."sort", seed."show_on_home"::boolean FROM (
  SELECT 1 AS "id", 'fun' AS "slug", '休闲娱乐' AS "name", '' AS "parent_slug", 'section' AS "kind", 'links' AS "content_kind", 1 AS "sort", 1 AS "show_on_home"
