  UNION ALL SELECT 15, 'resource', '资源工具', '', 'section', 'links', 3, 1
  UNION ALL SELECT 16, 'software', '软件', 'resource', 'tab', 'links', 1, 0
  UNION ALL SELECT 17, 'disk', '网盘', 'resource', 'tab', 'links', 2, 0
