  UNION ALL SELECT 25, 'life', '生活常用', '', 'section', 'links', 6, 1
  UNION ALL SELECT 26, 'shop', '购物', 'life', 'tab', 'links', 1, 0
  UNION ALL SELECT 27, 'job', '招聘', 'life', 'tab', 'links', 2, 0
  UNION ALL SELECT 28, 'finance', '财经', 'life', 'tab', 'links', 3, 0
