  UNION ALL SELECT 9, 'v-qq-2', 'anime', '腾讯视频动漫', 'https://v.qq.com/channel/cartoon', '正版动画', '动画,正版', '', '中文', '中国', '', '', '腾讯视频的动漫频道放正版动画，国产番和部分日本动画都有。会员和抢先看会标在集数上。

