  UNION ALL SELECT 14, 'y-qq', 'music', 'QQ音乐', 'https://y.qq.com', '正版曲库', '曲库,音乐', '', '中文', '中国', '', '', 'QQ音乐是正版曲库，歌单、专辑和排行都有。会员曲和免费曲在播放按钮上能看出来。

