  UNION ALL SELECT 316, 'napkin-ai', 'ai-office', 'Napkin AI', 'https://www.napkin.ai/', '把说明文字转成可编辑的流程图、思维导图或图表', '流程图,思维导图,汇报配图,AI', 'Napkin', '', '', '', '', 'Napkin AI 可以从已有文字生成流程图、思维导图等可视化内容，再调整节点和版式。它适合把报告里难读的长段落变成一张说明图，也能做演示文稿里的业务流程配图。

